import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isExiting, setIsExiting] = useState(false);
  const [status, setStatus] = useState("LOCATING_OPERATOR");

  useEffect(() => {
    const sequence = [
      { t: "LINKING_VANGUARD_NODE", d: 800 },
      { t: "AUTHENTICATING_BIO_ID", d: 1600 },
      { t: "SYSTEM_READY", d: 2400 }
    ];

    sequence.forEach(item => {
      setTimeout(() => setStatus(item.t), item.d);
    });

    setTimeout(() => setIsExiting(true), 3200);
    setTimeout(onComplete, 3800);
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#47510B] flex flex-col items-center justify-center relative overflow-hidden font-mono">

      {/* 1. BACKGROUND: Heavy Grid & Scanner Line */}
      <div className="absolute inset-0 opacity-10 bg-[grid-black_40px_40px]" />
      <div className="absolute inset-0 w-full h-[2px] bg-[#CAD23C] opacity-30 animate-scan z-10" />

      {/* 2. THE CORE UNIT */}
      <div className={`${isExiting ? "animate-shutter" : ""}`}>
        <div className="flex flex-col items-center">

          {/* Tactical Brackets around the Logo */}
          <div className="relative p-12">
            <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-[#CAD23C]" />
            <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-[#CAD23C]" />
            <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-[#CAD23C]" />
            <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-[#CAD23C]" />

            <motion.div 
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ duration: 0.5 }}
              className="flex items-center gap-1"
            >
              <span className="text-9xl font-black italic text-[#FDFAD8] tracking-tighter">T</span>
              <span className="text-9xl font-black italic text-[#FF5B03] drop-shadow-[4px_4px_0px_#2A3106]">2</span>
              <span className="text-9xl font-black italic text-[#FDFAD8] tracking-tighter">T</span>
            </motion.div>
          </div>

          {/* 3. DATA READOUT: The Worker Details */}
          <div className="mt-12 w-80 bg-black/20 p-4 border-l-4 border-[#CAD23C] shadow-industrial">
            <div className="flex justify-between items-center mb-2">
              <span className="text-[10px] text-[#CAD23C] font-bold">NODE_ID: 77-B109</span>
              <span className="text-[10px] text-[#FDFAD8] opacity-50">v4.0.2</span>
            </div>
            <div className="h-1 w-full bg-[#2A3106] overflow-hidden">
               <motion.div 
                 initial={{ x: "-100%" }}
                 animate={{ x: "0%" }}
                 transition={{ duration: 3, ease: "linear" }}
                 className="h-full bg-[#CAD23C]"
               />
            </div>
            <p className="mt-3 text-[12px] text-[#FFF24D] font-black tracking-widest text-center animate-pulse">
              {status}...
            </p>
          </div>
        </div>
      </div>

      {/* 4. PERIMETER DATA: Minimal Corners */}
      <div className="absolute bottom-6 left-6 text-[#FDFAD8] opacity-30 text-[9px] font-bold">
        LAT: 40.7128 | LONG: -74.0060
      </div>
      <div className="absolute bottom-6 right-6 text-[#FDFAD8] opacity-30 text-[9px] font-bold">
        OS: TRASH_2_TRACK_WORKER
      </div>
    </div>
  );
};

export default WorkerSplash;
